import math
import random


def sigmoid(x):
    if x >= 0:
        z = math.exp(-x)
        return 1 / (1 + z)
    z = math.exp(x)
    return z / (1 + z)


def leaky_relu(x, a=0.2):
    return x if x > 0 else a * x


def leaky_grad(x, a=0.2):
    return 1.0 if x > 0 else a


def randn_matrix(rows, cols, rng, scale=0.3):
    return [[rng.gauss(0, scale) for _ in range(cols)] for _ in range(rows)]


def matmul(W, x):
    return [sum(w * xi for w, xi in zip(row, x)) for row in W]


def add(a, b):
    return [x + y for x, y in zip(a, b)]


def init_mlp(in_dim, hidden, out_dim, rng):
    return {
        "W1": randn_matrix(hidden, in_dim, rng),
        "b1": [0.0] * hidden,
        "W2": randn_matrix(out_dim, hidden, rng),
        "b2": [0.0] * out_dim,
    }


def forward_g(z, G):
    pre1 = add(matmul(G["W1"], z), G["b1"])
    h = [leaky_relu(v) for v in pre1]
    pre2 = add(matmul(G["W2"], h), G["b2"])
    return pre2, h, pre1


def forward_d(x, D):
    pre1 = add(matmul(D["W1"], x), D["b1"])
    h = [leaky_relu(v) for v in pre1]
    pre2 = add(matmul(D["W2"], h), D["b2"])
    return sigmoid(pre2[0]), h, pre1, pre2[0]


def sample_real(n, rng):
    out = []
    for _ in range(n):
        if rng.random() < 0.5:
            out.append([rng.gauss(-2.0, 0.4)])
        else:
            out.append([rng.gauss(2.0, 0.4)])
    return out


def sample_noise(n, z_dim, rng):
    return [[rng.gauss(0, 1) for _ in range(z_dim)] for _ in range(n)]


def update_d(reals, fakes, D, lr):
    """Gradient step on D to maximize log D(x) + log(1 - D(G(z)))."""
    grads = {k: None for k in D}
    for part in D:
        if isinstance(D[part][0], list):
            grads[part] = [[0.0] * len(D[part][0]) for _ in D[part]]
        else:
            grads[part] = [0.0] * len(D[part])

    def accumulate(x, target):
        p, h, pre1, pre2 = forward_d(x, D)
        dL_dpre2 = p - target
        grads["b2"][0] += dL_dpre2
        for j in range(len(h)):
            grads["W2"][0][j] += dL_dpre2 * h[j]
        dh = [D["W2"][0][j] * dL_dpre2 for j in range(len(h))]
        dpre1 = [dh[j] * leaky_grad(pre1[j]) for j in range(len(h))]
        for j in range(len(h)):
            grads["b1"][j] += dpre1[j]
            for k in range(len(x)):
                grads["W1"][j][k] += dpre1[j] * x[k]

    for x in reals:
        accumulate(x, 1.0)
    for x in fakes:
        accumulate(x, 0.0)

    n = len(reals) + len(fakes)
    for part in D:
        if isinstance(D[part][0], list):
            for i in range(len(D[part])):
                for j in range(len(D[part][i])):
                    D[part][i][j] -= lr * grads[part][i][j] / n
        else:
            for i in range(len(D[part])):
                D[part][i] -= lr * grads[part][i] / n


def update_g(noise_batch, G, D, lr):
    """Non-saturating G loss: maximize log D(G(z)). Gradient flows through both."""
    grads = {k: None for k in G}
    for part in G:
        if isinstance(G[part][0], list):
            grads[part] = [[0.0] * len(G[part][0]) for _ in G[part]]
        else:
            grads[part] = [0.0] * len(G[part])

    for z in noise_batch:
        x_hat, g_h, g_pre1 = forward_g(z, G)
        p, d_h, d_pre1, d_pre2 = forward_d(x_hat, D)
        # dL/dpre2_D where L = -log(p) is -(1/p) * p*(1-p) = p - 1
        dL_dpre2 = p - 1.0
        # back through D to get dL / d x_hat
        dh_D = [D["W2"][0][j] * dL_dpre2 for j in range(len(d_h))]
        dpre1_D = [dh_D[j] * leaky_grad(d_pre1[j]) for j in range(len(d_h))]
        dL_dxhat = [0.0] * len(x_hat)
        for j in range(len(d_h)):
            for k in range(len(x_hat)):
                dL_dxhat[k] += D["W1"][j][k] * dpre1_D[j]
        # now back through G
        grads["b2"] = [grads["b2"][i] + dL_dxhat[i] for i in range(len(x_hat))]
        for i in range(len(x_hat)):
            for j in range(len(g_h)):
                grads["W2"][i][j] += dL_dxhat[i] * g_h[j]
        dh_G = [sum(G["W2"][i][j] * dL_dxhat[i] for i in range(len(x_hat)))
                for j in range(len(g_h))]
        dpre1_G = [dh_G[j] * leaky_grad(g_pre1[j]) for j in range(len(g_h))]
        for j in range(len(g_h)):
            grads["b1"][j] += dpre1_G[j]
            for k in range(len(z)):
                grads["W1"][j][k] += dpre1_G[j] * z[k]

    n = len(noise_batch)
    for part in G:
        if isinstance(G[part][0], list):
            for i in range(len(G[part])):
                for j in range(len(G[part][i])):
                    G[part][i][j] -= lr * grads[part][i][j] / n
        else:
            for i in range(len(G[part])):
                G[part][i] -= lr * grads[part][i] / n


def mean(xs):
    return sum(xs) / max(len(xs), 1)


def main():
    rng = random.Random(1)
    z_dim, hidden = 4, 16
    G = init_mlp(z_dim, hidden, 1, rng)
    D = init_mlp(1, hidden, 1, rng)

    batch, g_lr, d_lr = 32, 0.02, 0.01
    print("=== training 1-D GAN on two-mode Gaussian mixture ===")
    for step in range(1, 801):
        reals = sample_real(batch, rng)
        noise = sample_noise(batch, z_dim, rng)
        fakes = [forward_g(z, G)[0] for z in noise]
        update_d(reals, fakes, D, d_lr)

        noise = sample_noise(batch, z_dim, rng)
        update_g(noise, G, D, g_lr)

        if step % 100 == 0:
            probe_fakes = [forward_g(z, G)[0][0] for z in sample_noise(400, z_dim, rng)]
            mode_a = sum(1 for v in probe_fakes if v < 0)
            mode_b = 400 - mode_a
            d_real = mean([forward_d(x, D)[0] for x in sample_real(100, rng)])
            d_fake = mean([forward_d([v], D)[0] for v in probe_fakes])
            warn = "  [!] mode collapse" if min(mode_a, mode_b) < 50 else ""
            print(f"step {step:4d}: D(real)={d_real:.2f}  D(fake)={d_fake:.2f}  "
                  f"modeA={mode_a:3d}  modeB={mode_b:3d}{warn}")

    print()
    print("=== final 10 generator samples ===")
    for z in sample_noise(10, z_dim, rng):
        print(f"  G(z) = {forward_g(z, G)[0][0]:+.2f}")


if __name__ == "__main__":
    main()

import math
import random


def sigmoid(x):
    if x >= 0:
        z = math.exp(-x)
        return 1 / (1 + z)
    z = math.exp(x)
    return z / (1 + z)


def leaky(x, a=0.2):
    return x if x > 0 else a * x


def leaky_grad(x, a=0.2):
    return 1.0 if x > 0 else a


def randn_matrix(rows, cols, rng, scale=0.3):
    return [[rng.gauss(0, scale) for _ in range(cols)] for _ in range(rows)]


def matmul(W, x):
    return [sum(w * xi for w, xi in zip(row, x)) for row in W]


def add(a, b):
    return [x + y for x, y in zip(a, b)]


def one_hot(c, num):
    v = [0.0] * num
    v[c] = 1.0
    return v


def init_mlp(in_dim, hidden, out_dim, rng):
    return {
        "W1": randn_matrix(hidden, in_dim, rng),
        "b1": [0.0] * hidden,
        "W2": randn_matrix(out_dim, hidden, rng),
        "b2": [0.0] * out_dim,
    }


def g_forward(z, c, G, num_classes):
    inp = z + one_hot(c, num_classes)
    pre1 = add(matmul(G["W1"], inp), G["b1"])
    h = [leaky(v) for v in pre1]
    out = add(matmul(G["W2"], h), G["b2"])
    return out, h, pre1, inp


def d_forward(x, c, D, num_classes):
    inp = x + one_hot(c, num_classes)
    pre1 = add(matmul(D["W1"], inp), D["b1"])
    h = [leaky(v) for v in pre1]
    logit = add(matmul(D["W2"], h), D["b2"])[0]
    return sigmoid(logit), h, pre1, inp, logit


def sample_real_conditional(n, num_classes, rng):
    out = []
    for _ in range(n):
        c = rng.randrange(num_classes)
        if c == 0:
            x = rng.gauss(-2.0, 0.3)
        else:
            x = rng.gauss(2.0, 0.3)
        out.append(([x], c))
    return out


def update_d(reals, fakes, D, num_classes, lr):
    grads = init_grads(D)
    for (x, c) in reals:
        accumulate_d_grad(x, c, 1.0, D, num_classes, grads)
    for (x, c) in fakes:
        accumulate_d_grad(x, c, 0.0, D, num_classes, grads)
    n = len(reals) + len(fakes)
    apply_grads(D, grads, lr, n)


def accumulate_d_grad(x, c, target, D, num_classes, grads):
    p, h, pre1, inp, _ = d_forward(x, c, D, num_classes)
    dL_dpre2 = p - target
    grads["b2"][0] += dL_dpre2
    for j in range(len(h)):
        grads["W2"][0][j] += dL_dpre2 * h[j]
    dh = [D["W2"][0][j] * dL_dpre2 for j in range(len(h))]
    dpre1 = [dh[j] * leaky_grad(pre1[j]) for j in range(len(h))]
    for j in range(len(h)):
        grads["b1"][j] += dpre1[j]
        for k in range(len(inp)):
            grads["W1"][j][k] += dpre1[j] * inp[k]


def update_g(noise, cs, G, D, num_classes, lr, l1_w=0.0, targets=None):
    """Non-saturating G loss + optional conditional L1 toward a target."""
    grads = init_grads(G)
    for i, z in enumerate(noise):
        c = cs[i]
        x_hat, g_h, g_pre1, g_inp = g_forward(z, c, G, num_classes)
        p, d_h, d_pre1, d_inp, d_logit = d_forward(x_hat, c, D, num_classes)
        dL_dpre2 = p - 1.0
        dh_D = [D["W2"][0][j] * dL_dpre2 for j in range(len(d_h))]
        dpre1_D = [dh_D[j] * leaky_grad(d_pre1[j]) for j in range(len(d_h))]
        dL_dxhat = [0.0] * len(x_hat)
        for j in range(len(d_h)):
            for k in range(len(x_hat)):
                dL_dxhat[k] += D["W1"][j][k] * dpre1_D[j]
        if l1_w > 0 and targets is not None:
            for k in range(len(x_hat)):
                dL_dxhat[k] += l1_w * (1.0 if x_hat[k] > targets[i][k] else -1.0)
        grads["b2"] = [grads["b2"][i] + dL_dxhat[i] for i in range(len(x_hat))]
        for a in range(len(x_hat)):
            for b in range(len(g_h)):
                grads["W2"][a][b] += dL_dxhat[a] * g_h[b]
        dh_G = [sum(G["W2"][a][b] * dL_dxhat[a] for a in range(len(x_hat)))
                for b in range(len(g_h))]
        dpre1_G = [dh_G[j] * leaky_grad(g_pre1[j]) for j in range(len(g_h))]
        for j in range(len(g_h)):
            grads["b1"][j] += dpre1_G[j]
            for k in range(len(g_inp)):
                grads["W1"][j][k] += dpre1_G[j] * g_inp[k]
    apply_grads(G, grads, lr, len(noise))


def init_grads(net):
    grads = {}
    for k, v in net.items():
        if isinstance(v[0], list):
            grads[k] = [[0.0] * len(v[0]) for _ in v]
        else:
            grads[k] = [0.0] * len(v)
    return grads


def apply_grads(net, grads, lr, n):
    for k, v in net.items():
        if isinstance(v[0], list):
            for i in range(len(v)):
                for j in range(len(v[i])):
                    v[i][j] -= lr * grads[k][i][j] / n
        else:
            for i in range(len(v)):
                v[i] -= lr * grads[k][i] / n


def mean(xs):
    return sum(xs) / max(len(xs), 1)


def main():
    rng = random.Random(5)
    num_classes, z_dim, hidden = 2, 4, 16
    G = init_mlp(z_dim + num_classes, hidden, 1, rng)
    D = init_mlp(1 + num_classes, hidden, 1, rng)

    batch, g_lr, d_lr = 32, 0.02, 0.01
    print("=== conditional GAN on two-mode mixture (class 0 -> -2, class 1 -> +2) ===")
    for step in range(1, 601):
        reals = sample_real_conditional(batch, num_classes, rng)
        cs = [c for _, c in reals]
        noise = [[rng.gauss(0, 1) for _ in range(z_dim)] for _ in range(batch)]
        fakes = [(g_forward(noise[i], cs[i], G, num_classes)[0], cs[i]) for i in range(batch)]
        update_d(reals, fakes, D, num_classes, d_lr)

        noise = [[rng.gauss(0, 1) for _ in range(z_dim)] for _ in range(batch)]
        cs = [rng.randrange(num_classes) for _ in range(batch)]
        update_g(noise, cs, G, D, num_classes, g_lr)

        if step % 150 == 0:
            probes = {c: [] for c in range(num_classes)}
            for _ in range(300):
                c = rng.randrange(num_classes)
                z = [rng.gauss(0, 1) for _ in range(z_dim)]
                probes[c].append(g_forward(z, c, G, num_classes)[0][0])
            line = f"step {step:4d}:"
            for c in range(num_classes):
                line += f"  class {c}: mean {mean(probes[c]):+.2f}  (n={len(probes[c])})"
            print(line)

    print()
    print("=== sampling per class ===")
    for c in range(num_classes):
        z_batch = [[rng.gauss(0, 1) for _ in range(z_dim)] for _ in range(6)]
        outs = [g_forward(z, c, G, num_classes)[0][0] for z in z_batch]
        print(f"  class {c}: " + " ".join(f"{v:+.2f}" for v in outs))

    print()
    print("takeaway: G(z, c) learns a class-specific sampler.")
    print("          same architecture, one extra input, totally different samples.")


if __name__ == "__main__":
    main()

import math
import random


def sin_embed(t, T, dim=8):
    """Sinusoidal timestep embedding."""
    out = []
    half = dim // 2
    for i in range(half):
        freq = 1.0 / (10000 ** (i / max(half - 1, 1)))
        out.append(math.sin(t * freq))
        out.append(math.cos(t * freq))
    return out[:dim]


def tanh(v):
    return [math.tanh(x) for x in v]


def tanh_grad(h):
    return [1 - x * x for x in h]


def matmul(W, x):
    return [sum(w * xi for w, xi in zip(row, x)) for row in W]


def add(a, b):
    return [x + y for x, y in zip(a, b)]


def randn_matrix(rows, cols, rng, scale=0.3):
    return [[rng.gauss(0, scale) for _ in range(cols)] for _ in range(rows)]


def init_net(x_dim, t_dim, hidden, rng):
    return {
        "W1": randn_matrix(hidden, x_dim + t_dim, rng),
        "b1": [0.0] * hidden,
        "W2": randn_matrix(hidden, hidden, rng),
        "b2": [0.0] * hidden,
        "W3": randn_matrix(x_dim, hidden, rng),
        "b3": [0.0] * x_dim,
    }


def forward(x_t, t_embed, net):
    inp = x_t + t_embed
    pre1 = add(matmul(net["W1"], inp), net["b1"])
    h1 = tanh(pre1)
    pre2 = add(matmul(net["W2"], h1), net["b2"])
    h2 = tanh(pre2)
    eps_hat = add(matmul(net["W3"], h2), net["b3"])
    return eps_hat, {"inp": inp, "h1": h1, "h2": h2, "pre1": pre1, "pre2": pre2}


def backward(target_eps, eps_hat, cache, net):
    grads = {k: None for k in net}
    for part in net:
        if isinstance(net[part][0], list):
            grads[part] = [[0.0] * len(net[part][0]) for _ in net[part]]
        else:
            grads[part] = [0.0] * len(net[part])

    d_out = [2 * (a - b) for a, b in zip(eps_hat, target_eps)]
    for i in range(len(d_out)):
        grads["b3"][i] += d_out[i]
        for j in range(len(cache["h2"])):
            grads["W3"][i][j] += d_out[i] * cache["h2"][j]
    d_h2 = [sum(net["W3"][i][j] * d_out[i] for i in range(len(d_out)))
            for j in range(len(cache["h2"]))]
    d_pre2 = [d_h2[j] * tanh_grad(cache["h2"])[j] for j in range(len(cache["h2"]))]
    for j in range(len(cache["h2"])):
        grads["b2"][j] += d_pre2[j]
        for k in range(len(cache["h1"])):
            grads["W2"][j][k] += d_pre2[j] * cache["h1"][k]
    d_h1 = [sum(net["W2"][j][k] * d_pre2[j] for j in range(len(cache["h2"])))
            for k in range(len(cache["h1"]))]
    d_pre1 = [d_h1[j] * tanh_grad(cache["h1"])[j] for j in range(len(cache["h1"]))]
    for j in range(len(cache["h1"])):
        grads["b1"][j] += d_pre1[j]
        for k in range(len(cache["inp"])):
            grads["W1"][j][k] += d_pre1[j] * cache["inp"][k]
    return grads


def apply_update(net, grads, lr):
    for k, v in net.items():
        if isinstance(v[0], list):
            for i in range(len(v)):
                for j in range(len(v[i])):
                    v[i][j] -= lr * grads[k][i][j]
        else:
            for i in range(len(v)):
                v[i] -= lr * grads[k][i]


def make_schedule(T):
    betas = [1e-4 + (0.02 - 1e-4) * t / (T - 1) for t in range(T)]
    alphas = [1 - b for b in betas]
    alpha_bars, cum = [], 1.0
    for a in alphas:
        cum *= a
        alpha_bars.append(cum)
    return betas, alphas, alpha_bars


def sample_data(rng):
    return rng.gauss(-2.0, 0.4) if rng.random() < 0.5 else rng.gauss(2.0, 0.4)


def train(net, alpha_bars, T, steps, lr, t_dim, rng):
    for step in range(steps):
        x0 = sample_data(rng)
        t = rng.randrange(T)
        a_bar = alpha_bars[t]
        eps = rng.gauss(0, 1)
        x_t = math.sqrt(a_bar) * x0 + math.sqrt(1 - a_bar) * eps
        t_emb = sin_embed(t, T, t_dim)
        eps_hat, cache = forward([x_t], t_emb, net)
        grads = backward([eps], eps_hat, cache, net)
        apply_update(net, grads, lr)
        if (step + 1) % 500 == 0:
            loss = (eps_hat[0] - eps) ** 2
            print(f"step {step+1:5d}: loss {loss:.4f}")


def sample(net, alphas, alpha_bars, T, t_dim, rng):
    x = rng.gauss(0, 1)
    for t in range(T - 1, -1, -1):
        t_emb = sin_embed(t, T, t_dim)
        eps_hat, _ = forward([x], t_emb, net)
        beta_t = 1 - alphas[t]
        mean = (x - beta_t / math.sqrt(1 - alpha_bars[t]) * eps_hat[0]) / math.sqrt(alphas[t])
        if t > 0:
            x = mean + math.sqrt(beta_t) * rng.gauss(0, 1)
        else:
            x = mean
    return x


def histogram(samples, lo=-5.0, hi=5.0, bins=30):
    width = (hi - lo) / bins
    counts = [0] * bins
    for s in samples:
        if lo <= s < hi:
            counts[int((s - lo) / width)] += 1
    peak = max(counts) or 1
    height = 8
    rows = []
    for r in range(height, 0, -1):
        thr = peak * r / height
        rows.append("".join("#" if c >= thr else " " for c in counts))
    rows.append("-" * bins)
    return "\n".join(rows)


def main():
    rng = random.Random(13)
    T, t_dim, hidden = 40, 8, 24
    _, alphas, alpha_bars = make_schedule(T)
    net = init_net(1, t_dim, hidden, rng)

    print("=== training DDPM on two-mode 1-D mixture ===")
    train(net, alpha_bars, T, steps=4000, lr=0.01, t_dim=t_dim, rng=rng)

    print()
    print("=== sampling ===")
    samples = [sample(net, alphas, alpha_bars, T, t_dim, rng) for _ in range(500)]
    print(histogram(samples))
    m = sum(samples) / len(samples)
    pos = sum(1 for s in samples if s > 0)
    print(f"mean {m:+.3f}, modeA(<0)={500-pos}, modeB(>0)={pos}")

    print()
    print("takeaway: trained noise predictor + reverse chain reproduces both modes.")
    print("          same loss function that scales to images, video, 3D.")


if __name__ == "__main__":
    main()

