    return [x + y for x, y in zip(a, b)]


def randn_matrix(rows, cols, rng, scale=0.3):
    return [[rng.gauss(0, scale) for _ in range(cols)] for _ in range(rows)]


NULL_CLASS = 2


def init_net(x_dim, t_dim, c_dim, hidden, rng):
    return {
        "W1": randn_matrix(hidden, x_dim + t_dim + c_dim, rng),
        "b1": [0.0] * hidden,
        "W2": randn_matrix(hidden, hidden, rng),
        "b2": [0.0] * hidden,
        "W3": randn_matrix(x_dim, hidden, rng),
        "b3": [0.0] * x_dim,
    }


def forward(x_t, t_emb, c_emb, net):
    inp = x_t + t_emb + c_emb
    pre1 = add(matmul(net["W1"], inp), net["b1"])
    h1 = tanh(pre1)
    pre2 = add(matmul(net["W2"], h1), net["b2"])
    h2 = tanh(pre2)
    out = add(matmul(net["W3"], h2), net["b3"])
    return out, {"inp": inp, "h1": h1, "h2": h2}


def backward(target, out, cache, net):
    grads = {k: None for k in net}
    for part in net:
        if isinstance(net[part][0], list):
            grads[part] = [[0.0] * len(net[part][0]) for _ in net[part]]
        else:
            grads[part] = [0.0] * len(net[part])
    d_out = [2 * (a - b) for a, b in zip(out, target)]
    for i in range(len(d_out)):
        grads["b3"][i] += d_out[i]
        for j in range(len(cache["h2"])):
            grads["W3"][i][j] += d_out[i] * cache["h2"][j]
    d_h2 = [sum(net["W3"][i][j] * d_out[i] for i in range(len(d_out)))
            for j in range(len(cache["h2"]))]
    d_pre2 = [d_h2[j] * tanh_grad(cache["h2"])[j] for j in range(len(cache["h2"]))]
    for j in range(len(cache["h2"])):
        grads["b2"][j] += d_pre2[j]
        for k in range(len(cache["h1"])):
            grads["W2"][j][k] += d_pre2[j] * cache["h1"][k]
    d_h1 = [sum(net["W2"][j][k] * d_pre2[j] for j in range(len(cache["h2"])))
            for k in range(len(cache["h1"]))]
    d_pre1 = [d_h1[j] * tanh_grad(cache["h1"])[j] for j in range(len(cache["h1"]))]
    for j in range(len(cache["h1"])):
        grads["b1"][j] += d_pre1[j]
        for k in range(len(cache["inp"])):
            grads["W1"][j][k] += d_pre1[j] * cache["inp"][k]
    return grads


def apply(net, grads, lr):
    for k, v in net.items():
        if isinstance(v[0], list):
            for i in range(len(v)):
                for j in range(len(v[i])):
                    v[i][j] -= lr * grads[k][i][j]
        else:
            for i in range(len(v)):
                v[i] -= lr * grads[k][i]


def make_schedule(T):
    betas = [1e-4 + (0.02 - 1e-4) * t / (T - 1) for t in range(T)]
    alphas = [1 - b for b in betas]
    bars, cum = [], 1.0
    for a in alphas:
        cum *= a
        bars.append(cum)
    return alphas, bars


def encode(x):
    return x * 0.5


def decode(z):
    return z * 2.0


def sample_data(rng):
    c = rng.randrange(2)
    x = rng.gauss(-2.0 if c == 0 else 2.0, 0.4)
    return x, c


def main():
    rng = random.Random(11)
    T, t_dim, hidden = 40, 8, 32
    num_classes_inc_null = 3
    alphas, alpha_bars = make_schedule(T)
    net = init_net(1, t_dim, num_classes_inc_null, hidden, rng)

    print("=== training class-conditional latent diffusion with CFG dropout ===")
    for step in range(4000):
        x0, c = sample_data(rng)
        z0 = encode(x0)
        t = rng.randrange(T)
        eps = rng.gauss(0, 1)
        z_t = math.sqrt(alpha_bars[t]) * z0 + math.sqrt(1 - alpha_bars[t]) * eps
        use_c = NULL_CLASS if rng.random() < 0.1 else c
        c_emb = one_hot(use_c, num_classes_inc_null)
        t_emb = sin_embed(t, T, t_dim)
        out, cache = forward([z_t], t_emb, c_emb, net)
        grads = backward([eps], out, cache, net)
        apply(net, grads, 0.01)
        if (step + 1) % 1000 == 0:
            print(f"  step {step+1:5d}")

    def sample(c_target, w):
        z = rng.gauss(0, 1)
        for t in range(T - 1, -1, -1):
            t_emb = sin_embed(t, T, t_dim)
            eps_c, _ = forward([z], t_emb, one_hot(c_target, num_classes_inc_null), net)
            eps_u, _ = forward([z], t_emb, one_hot(NULL_CLASS, num_classes_inc_null), net)
            eps_cfg = (1 + w) * eps_c[0] - w * eps_u[0]
            beta_t = 1 - alphas[t]
            mean = (z - beta_t / math.sqrt(1 - alpha_bars[t]) * eps_cfg) / math.sqrt(alphas[t])
            if t > 0:
                z = mean + math.sqrt(beta_t) * rng.gauss(0, 1)
            else:
                z = mean
        return decode(z)

    print()
    print("=== CFG sweep: per-class mean over 200 samples ===")
    for w in [0.0, 1.0, 3.0, 7.0]:
        samples = {0: [], 1: []}
        for _ in range(200):
            c = rng.randrange(2)
            samples[c].append(sample(c, w))
        m0 = sum(samples[0]) / len(samples[0])
        m1 = sum(samples[1]) / len(samples[1])
        print(f"  w={w:.1f}: class 0 mean {m0:+.2f}  class 1 mean {m1:+.2f}")

    print()
    print("takeaway: same DDPM loss, just running on encoded z.")
    print("          CFG scales conditioning strength without retraining.")


if __name__ == "__main__":
    main()

import math
import random


def sin_embed(t, T, dim=8):
    out = []
    half = dim // 2
    for i in range(half):
        freq = 1.0 / (10000 ** (i / max(half - 1, 1)))
        out.append(math.sin(t * freq))
        out.append(math.cos(t * freq))
    return out[:dim]


def tanh(v):
    return [math.tanh(x) for x in v]


def tanh_grad(h):
    return [1 - x * x for x in h]


def matmul(W, x):
    return [sum(w * xi for w, xi in zip(row, x)) for row in W]


def add(a, b):
    return [x + y for x, y in zip(a, b)]


def randn_matrix(rows, cols, rng, scale=0.3):
    return [[rng.gauss(0, scale) for _ in range(cols)] for _ in range(rows)]


def init_net(x_dim, t_dim, hidden, rng):
    return {
        "W1": randn_matrix(hidden, x_dim + t_dim, rng),
        "b1": [0.0] * hidden,
        "W2": randn_matrix(hidden, hidden, rng),
        "b2": [0.0] * hidden,
        "W3": randn_matrix(x_dim, hidden, rng),
        "b3": [0.0] * x_dim,
    }


def forward(x_t, t_emb, net):
    inp = list(x_t) + list(t_emb)
    pre1 = add(matmul(net["W1"], inp), net["b1"])
    h1 = tanh(pre1)
    pre2 = add(matmul(net["W2"], h1), net["b2"])
    h2 = tanh(pre2)
    out = add(matmul(net["W3"], h2), net["b3"])
    return out, {"inp": inp, "h1": h1, "h2": h2}


def backward(target, out, cache, net):
    grads = {k: None for k in net}
    for p in net:
        if isinstance(net[p][0], list):
            grads[p] = [[0.0] * len(net[p][0]) for _ in net[p]]
        else:
            grads[p] = [0.0] * len(net[p])
    d_out = [2 * (a - b) for a, b in zip(out, target)]
    for i in range(len(d_out)):
        grads["b3"][i] += d_out[i]
        for j in range(len(cache["h2"])):
            grads["W3"][i][j] += d_out[i] * cache["h2"][j]
    d_h2 = [sum(net["W3"][i][j] * d_out[i] for i in range(len(d_out)))
            for j in range(len(cache["h2"]))]
    d_pre2 = [d_h2[j] * tanh_grad(cache["h2"])[j] for j in range(len(cache["h2"]))]
    for j in range(len(cache["h2"])):
        grads["b2"][j] += d_pre2[j]
        for k in range(len(cache["h1"])):
            grads["W2"][j][k] += d_pre2[j] * cache["h1"][k]
    d_h1 = [sum(net["W2"][j][k] * d_pre2[j] for j in range(len(cache["h2"])))
            for k in range(len(cache["h1"]))]
    d_pre1 = [d_h1[j] * tanh_grad(cache["h1"])[j] for j in range(len(cache["h1"]))]
    for j in range(len(cache["h1"])):
        grads["b1"][j] += d_pre1[j]
        for k in range(len(cache["inp"])):
            grads["W1"][j][k] += d_pre1[j] * cache["inp"][k]
    return grads


def apply(net, grads, lr):
    for k, v in net.items():
        if isinstance(v[0], list):
            for i in range(len(v)):
                for j in range(len(v[i])):
                    v[i][j] -= lr * grads[k][i][j]
        else:
            for i in range(len(v)):
                v[i] -= lr * grads[k][i]


def make_schedule(T):
    betas = [1e-4 + (0.02 - 1e-4) * t / (T - 1) for t in range(T)]
    alphas = [1 - b for b in betas]
    bars, cum = [], 1.0
    for a in alphas:
        cum *= a
        bars.append(cum)
    return alphas, bars


def sample_data(rng, d=5):
    cluster = rng.choice([0, 1])
    center = [-1.0 if cluster == 0 else 1.0] * d
    return [c + rng.gauss(0, 0.2) for c in center], cluster


def train(net, alpha_bars, T, steps, lr, t_dim, d, rng):
    for step in range(steps):
        x0, _ = sample_data(rng, d)
        t = rng.randrange(T)
        eps = [rng.gauss(0, 1) for _ in range(d)]
        a_bar = alpha_bars[t]
        x_t = [math.sqrt(a_bar) * x0[i] + math.sqrt(1 - a_bar) * eps[i] for i in range(d)]
        t_emb = sin_embed(t, T, t_dim)
        out, cache = forward(x_t, t_emb, net)
        grads = backward(eps, out, cache, net)
        apply(net, grads, lr)


def sample_unconditional(net, alphas, alpha_bars, T, t_dim, d, rng):
    x = [rng.gauss(0, 1) for _ in range(d)]
    for t in range(T - 1, -1, -1):
        t_emb = sin_embed(t, T, t_dim)
        eps_hat, _ = forward(x, t_emb, net)
        beta_t = 1 - alphas[t]
        mean = [(x[i] - beta_t / math.sqrt(1 - alpha_bars[t]) * eps_hat[i]) / math.sqrt(alphas[t])
                for i in range(d)]
        if t > 0:
            x = [mean[i] + math.sqrt(beta_t) * rng.gauss(0, 1) for i in range(d)]
        else:
            x = mean
    return x


def inpaint(net, alphas, alpha_bars, T, t_dim, d, clean, mask, rng):
    """mask[i] == True means that dim is to be regenerated. Unmasked dims pinned to clean."""
    x = [rng.gauss(0, 1) for _ in range(d)]
    for t in range(T - 1, -1, -1):
        a_bar = alpha_bars[t]
        for i in range(d):
            if not mask[i]:
                x[i] = math.sqrt(a_bar) * clean[i] + math.sqrt(1 - a_bar) * rng.gauss(0, 1)
        t_emb = sin_embed(t, T, t_dim)
        eps_hat, _ = forward(x, t_emb, net)
        beta_t = 1 - alphas[t]
        mean = [(x[i] - beta_t / math.sqrt(1 - alpha_bars[t]) * eps_hat[i]) / math.sqrt(alphas[t])
                for i in range(d)]
        if t > 0:
            x = [mean[i] + math.sqrt(beta_t) * rng.gauss(0, 1) for i in range(d)]
        else:
            x = mean
    for i in range(d):
        if not mask[i]:
            x[i] = clean[i]
    return x


def main():
    rng = random.Random(5)
    T, t_dim, hidden, d = 40, 8, 32, 5
    alphas, alpha_bars = make_schedule(T)
    net = init_net(d, t_dim, hidden, rng)

    print("=== training 5-D DDPM on two-cluster mixture ===")
    train(net, alpha_bars, T, steps=5000, lr=0.01, t_dim=t_dim, d=d, rng=rng)

    print()
    print("=== inpainting: pin dims 0-2, regenerate dims 3-4 ===")
    for trial in range(5):
        clean, cluster = sample_data(rng, d)
        mask = [False, False, False, True, True]
        out = inpaint(net, alphas, alpha_bars, T, t_dim, d, clean, mask, rng)
        label = "neg cluster" if cluster == 0 else "pos cluster"
        print(f"  {label}: pinned={[f'{clean[i]:+.2f}' for i in range(3)]}  "
              f"filled={[f'{out[i]:+.2f}' for i in range(3, 5)]}")

    print()
    print("=== outpainting (mask dims 0-1, pin 2-4) ===")
    for trial in range(3):
        clean, cluster = sample_data(rng, d)
        mask = [True, True, False, False, False]
        out = inpaint(net, alphas, alpha_bars, T, t_dim, d, clean, mask, rng)
        print(f"  pinned tail=[{clean[2]:+.2f}, {clean[3]:+.2f}, {clean[4]:+.2f}]  "
              f"filled head=[{out[0]:+.2f}, {out[1]:+.2f}]")

    print()
    print("takeaway: the filled dims match the cluster sign of the pinned dims.")
    print("          that is why inpainting looks coherent with the surroundings.")


if __name__ == "__main__":
    main()

import math
import random


SIZE = 12  # small image grid for speed


def make_target(size):
    """Target: a smooth bright blob in the upper-left, dimmer one in the lower-right."""
    target = [[0.0] * size for _ in range(size)]
    for y in range(size):
        for x in range(size):
            d1 = ((x - 3) ** 2 + (y - 3) ** 2) / 6.0
            d2 = ((x - 8) ** 2 + (y - 8) ** 2) / 8.0
            target[y][x] = math.exp(-d1) + 0.5 * math.exp(-d2)
    return target


def init_gaussians(n, rng):
    return [{
        "pos": [rng.uniform(2, SIZE - 2), rng.uniform(2, SIZE - 2)],
        "sigma": rng.uniform(0.8, 2.5),
        "color": rng.uniform(0.2, 0.8),
    } for _ in range(n)]


def gaussian_value(x, y, g):
    dx = x - g["pos"][0]
    dy = y - g["pos"][1]
    d2 = dx * dx + dy * dy
    return g["color"] * math.exp(-d2 / (2 * g["sigma"] ** 2))


def render(gaussians):
    img = [[0.0] * SIZE for _ in range(SIZE)]
    for y in range(SIZE):
        for x in range(SIZE):
            for g in gaussians:
                img[y][x] += gaussian_value(x, y, g)
    return img


def mse(a, b):
    total = 0.0
    for y in range(SIZE):
        for x in range(SIZE):
            total += (a[y][x] - b[y][x]) ** 2
    return total / (SIZE * SIZE)


def finite_diff_step(gaussians, target, lr, eps=0.1):
    base = render(gaussians)
    base_loss = mse(base, target)
    for g in gaussians:
        for key in ("pos", "sigma", "color"):
            if isinstance(g[key], list):
                for i in range(len(g[key])):
                    g[key][i] += eps
                    up = mse(render(gaussians), target)
                    g[key][i] -= eps
                    grad = (up - base_loss) / eps
                    g[key][i] -= lr * grad
            else:
                g[key] += eps
                up = mse(render(gaussians), target)
                g[key] -= eps
                grad = (up - base_loss) / eps
                g[key] -= lr * grad
    return base_loss


def ascii_img(img, chars=" .:;+*#@"):
    peak = max(max(row) for row in img) or 1.0
    lines = []
    for row in img:
        line = "".join(chars[min(len(chars) - 1, int(v / peak * (len(chars) - 1)))]
                       for v in row)
        lines.append(line)
    return "\n".join(lines)


def main():
    rng = random.Random(23)
    target = make_target(SIZE)

    print("=== target image ===")
    print(ascii_img(target))
    print()

    for n in [2, 4, 8]:
        rng_local = random.Random(7 + n)
        gaussians = init_gaussians(n, rng_local)
        print(f"=== fit {n} Gaussians ===")
        for step in range(30):
            loss = finite_diff_step(gaussians, target, lr=0.5, eps=0.2)
        print(f"final loss (MSE): {loss:.4f}")
        print(ascii_img(render(gaussians)))
        print()

    print("takeaway: a few differentiable Gaussians can approximate smooth targets.")
    print("          scale to 1M splats in 3D, render via alpha compositing = 3D-GS.")


if __name__ == "__main__":
    main()

import math
import random


def tanh(v):
    return [math.tanh(x) for x in v]


def tanh_grad(h):
    return [1 - x * x for x in h]


def matmul(W, x):
    return [sum(w * xi for w, xi in zip(row, x)) for row in W]


def add(a, b):
    return [x + y for x, y in zip(a, b)]


def randn_matrix(rows, cols, rng, scale=0.3):
    return [[rng.gauss(0, scale) for _ in range(cols)] for _ in range(rows)]


def init_net(in_dim, hidden, out_dim, rng):
    return {
        "W1": randn_matrix(hidden, in_dim, rng),
        "b1": [0.0] * hidden,
        "W2": randn_matrix(hidden, hidden, rng),
        "b2": [0.0] * hidden,
        "W3": randn_matrix(out_dim, hidden, rng),
        "b3": [0.0] * out_dim,
    }


def forward(x, t, net):
    inp = [x, t, t * t, math.sin(2 * math.pi * t), math.cos(2 * math.pi * t)]
    pre1 = add(matmul(net["W1"], inp), net["b1"])
    h1 = tanh(pre1)
    pre2 = add(matmul(net["W2"], h1), net["b2"])
    h2 = tanh(pre2)
    out = add(matmul(net["W3"], h2), net["b3"])
    return out[0], {"inp": inp, "h1": h1, "h2": h2}


def backward(target, out, cache, net):
    grads = {k: None for k in net}
    for p in net:
        if isinstance(net[p][0], list):
            grads[p] = [[0.0] * len(net[p][0]) for _ in net[p]]
        else:
            grads[p] = [0.0] * len(net[p])
    d_out = 2 * (out - target)
    grads["b3"][0] += d_out
    for j in range(len(cache["h2"])):
        grads["W3"][0][j] += d_out * cache["h2"][j]
    d_h2 = [net["W3"][0][j] * d_out for j in range(len(cache["h2"]))]
    d_pre2 = [d_h2[j] * tanh_grad(cache["h2"])[j] for j in range(len(cache["h2"]))]
    for j in range(len(cache["h2"])):
        grads["b2"][j] += d_pre2[j]
        for k in range(len(cache["h1"])):
            grads["W2"][j][k] += d_pre2[j] * cache["h1"][k]
    d_h1 = [sum(net["W2"][j][k] * d_pre2[j] for j in range(len(cache["h2"])))
            for k in range(len(cache["h1"]))]
    d_pre1 = [d_h1[j] * tanh_grad(cache["h1"])[j] for j in range(len(cache["h1"]))]
    for j in range(len(cache["h1"])):
        grads["b1"][j] += d_pre1[j]
        for k in range(len(cache["inp"])):
            grads["W1"][j][k] += d_pre1[j] * cache["inp"][k]
    return grads


def apply(net, grads, lr):
    for k, v in net.items():
        if isinstance(v[0], list):
            for i in range(len(v)):
                for j in range(len(v[i])):
                    v[i][j] -= lr * grads[k][i][j]
        else:
            for i in range(len(v)):
                v[i] -= lr * grads[k][i]


def sample_data(rng):
    return rng.gauss(-2.0, 0.3) if rng.random() < 0.5 else rng.gauss(2.0, 0.3)


def train(net, steps, lr, rng):
    for _ in range(steps):
        x0 = sample_data(rng)
        x1 = rng.gauss(0, 1)
        t = rng.random()
        x_t = t * x1 + (1 - t) * x0
        target = x1 - x0
        pred, cache = forward(x_t, t, net)
        grads = backward(target, pred, cache, net)
        apply(net, grads, lr)


def sample(net, num_steps, rng):
    x = rng.gauss(0, 1)
    dt = 1.0 / num_steps
    for i in range(num_steps):
        t = 1.0 - i * dt
        v, _ = forward(x, t, net)
        x -= dt * v
    return x


def histogram(samples, lo=-5.0, hi=5.0, bins=30):
    width = (hi - lo) / bins
    counts = [0] * bins
    for s in samples:
        if lo <= s < hi:
            counts[int((s - lo) / width)] += 1
    peak = max(counts) or 1
    height = 6
    rows = []
    for r in range(height, 0, -1):
        thr = peak * r / height
        rows.append("".join("#" if c >= thr else " " for c in counts))
    rows.append("-" * bins)
    return "\n".join(rows)


def main():
    rng = random.Random(31)
    net = init_net(in_dim=5, hidden=24, out_dim=1, rng=rng)

    print("=== training flow matching on two-mode mixture ===")
    train(net, steps=6000, lr=0.01, rng=rng)

    print()
    for num_steps in [1, 2, 4, 8, 20]:
        samples = [sample(net, num_steps, rng) for _ in range(500)]
        m = sum(samples) / len(samples)
        pos = sum(1 for s in samples if s > 0)
        print(f"=== {num_steps}-step Euler integration ===")
        print(histogram(samples))
        print(f"mean {m:+.2f}, left mode = {500 - pos}, right mode = {pos}")
        print()

    print("takeaway: straight-line flow matching lets Euler work at 4-8 steps.")
    print("          DDPM needs 20+ for similar quality in this toy.")


